python3 - <<'EOF'
import json, base64
from pathlib import Path
sig_lens = []
sample = None
for f in (Path.home()/".claude"/"projects").rglob("*.jsonl"):
    for line in open(f, errors="replace"):
        if '"thinking"' not in line: continue
        try: rec = json.loads(line)
        except: continue
        msg = rec.get("message") or {}
        for b in (msg.get("content") or []):
            if isinstance(b, dict) and b.get("type") == "thinking":
                sig_lens.append((len(b.get("thinking","")), len(b.get("signature",""))))
                if sample is None: sample = b.get("signature","")
print("blocks:", len(sig_lens))
print("nonempty thinking text:", sum(1 for t,_ in sig_lens if t>0))
print("sig len min/max:", min(s for _,s in sig_lens), max(s for _,s in sig_lens))
raw = base64.b64decode(sample)
print("decoded sig bytes:", len(raw))
print("printable runs:", [x for x in raw.split(b'\x00') if len(x)>4][:5])
EOF
